/**
 * @summary Search campaigns
 */
export const searchCampaigns = (
  params?: SearchCampaignsParams,
  options?: SecondParameter<typeof customPortailFetch>,
  signal?: AbortSignal,
) => {
  return customPortailFetch<CampaignSummaryDto[]>(
    { url: `/api/campaigns/search`, method: "GET", params, signal },
    options,
  );
};

export const getSearchCampaignsQueryKey = (params?: SearchCampaignsParams) => {
  return [`/api/campaigns/search`, ...(params ? [params] : [])] as const;
};

export const getSearchCampaignsQueryOptions = <
  TData = Awaited<ReturnType<typeof searchCampaigns>>,
  TError = ApiError,
>(
  params?: SearchCampaignsParams,
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof searchCampaigns>>, TError, TData>>;
    request?: SecondParameter<typeof customPortailFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getSearchCampaignsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof searchCampaigns>>> = ({ signal }) =>
    searchCampaigns(params, requestOptions, signal);

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof searchCampaigns>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData> };
};

export type SearchCampaignsQueryResult = NonNullable<Awaited<ReturnType<typeof searchCampaigns>>>;
export type SearchCampaignsQueryError = ApiError;

